//! Generated protobuf types and ConnectRPC stubs for the factory.
//!
//! - [`workgraph::v1`]: the work graph (`Node`, `Edge`, `Schema`, the core
//!   payload kinds, annotations and runs).
//! - [`v1`]: the control plane's `FactoryService` API.
//!
//! Generated by `just factory gen` into `src/proto/` and `src/connect_gen/`;
//! don't edit those by hand.

use std::sync::Mutex;

use buffa::type_registry::TypeRegistry;

// Kept as `crate::proto`: the connect code names it by that path.
mod proto;
pub use proto::factory::{v1, workgraph};

/// The generated ConnectRPC service trait, router and client.
#[path = "connect_gen/mod.rs"]
pub mod connect_gen;

pub use buffa;
pub use buffa_types;

/// An encoded `google.protobuf.FileDescriptorSet` for `factory.workgraph.v1`
/// and `factory.v1`, with their imports. Built by `just factory-gen`.
pub const DESCRIPTORS: &[u8] = include_bytes!("descriptors.binpb");

/// Add the well-known types and the factory's own types to `reg`.
pub fn add_types(reg: &mut TypeRegistry) {
    buffa_types::register_wkt_types(reg);
    proto::factory::workgraph::v1::register_types(reg);
    proto::factory::v1::register_types(reg);
}

/// A function that adds an extension's payload types to a registry, such as
/// a generated package's `register_types`.
pub type AddTypes = fn(&mut TypeRegistry);

/// The type adders installed so far, beyond the base set.
static INSTALLED: Mutex<Option<Vec<AddTypes>>> = Mutex::new(None);

/// Install the global type registry so `google.protobuf.Any` payloads
/// serialize as readable proto-JSON: the well-known types, the factory's own
/// types, and the types each of `extra` adds (an extension's payload types).
///
/// The registry is process-wide and only grows: each call installs the union
/// of everything installed so far, so two factories in one process with
/// different extensions both keep their types. Idempotent.
pub fn install_types(extra: &[AddTypes]) {
    let mut installed = INSTALLED.lock().unwrap_or_else(|e| e.into_inner());
    let adders = installed.get_or_insert_with(Vec::new);
    let before = adders.len();
    let first = before == 0 && !BASE.load(std::sync::atomic::Ordering::Acquire);
    for add in extra {
        if !adders.iter().any(|a| std::ptr::fn_addr_eq(*a, *add)) {
            adders.push(*add);
        }
    }
    if !first && adders.len() == before {
        return;
    }
    let mut reg = TypeRegistry::new();
    add_types(&mut reg);
    for add in adders.iter() {
        add(&mut reg);
    }
    buffa::type_registry::set_type_registry(reg);
    BASE.store(true, std::sync::atomic::Ordering::Release);
}

static BASE: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// Install the base registry (the well-known types and the factory's own)
/// if nothing is installed yet. Idempotent; call it before any JSON encoding.
pub fn register_types() {
    install_types(&[]);
}
